// ref:
// https://iquilezles.org/articles/distfunctions2d/
// https://www.shadertoy.com/view/stcfzn

float rand(vec2 co){
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

// a: from, b: to, th: width
float sdOrientedBox( in vec2 p, in vec2 a, in vec2 b, float th )
{
    float l = length(b-a);
    vec2  d = (b-a)/l;
    vec2  q = p-(a+b)*0.5;
          q = mat2(d.x,-d.y,d.y,d.x)*q;
          q = abs(q)-vec2(l*0.5,th);
    return length(max(q,0.0)) + min(max(q.x,q.y),0.0);    
}

float line(vec2 p, vec2 offset, float s, float len, float speed, float duration, float timeOffset, float power) {
    float r = pow(mod(iTime * speed + timeOffset, duration) / duration, power); // 0 - 1
    float f = smoothstep(.8, .5, r);
    float fx = .7 + pow(r, .1) * -.6;
    float tx = fx + (1. - r) * len;
    vec2 fp = vec2(fx, offset.y);
    vec2 tp = vec2(mix(tx, fx, min(pow(r, .8), .999)), offset.y);
    float d = sdOrientedBox(p, fp,  tp, s * f);
    // return smoothstep(.05, 0., d);
    return (1. - step(s * f, d)) * f;
}

vec3 lines(vec2 p, vec2 rep, float s, float speed, float baseDuration, vec3 color) {
    vec2 id = floor(p * rep);
    vec2 hash = vec2(rand(id + 1.));
    p.x += sin(mod(id.y * 10., 6.28)) * 5.;
    id = floor(p * rep);
    p = fract(p * rep);
    hash = vec2(rand(id + 4.));
    vec3 col = line(p, vec2(0., .3), s, .8, speed, baseDuration + hash.x * .6,  .5 + hash.y * 20., .4) * color;
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 p = (fragCoord * 2. - iResolution.xy) / iResolution.y;
    vec2 m = (iMouse.xy * 2. - iResolution.xy) / iResolution.y;

    float t = iTime;

    p += vec2(sin(p.x * .4 + t * .4), cos(p.y * 3. + t * .05) * .1) * .75;

    vec3 col = vec3(0.);

    col += lines(p + vec2(0., 0.) - vec2(-t * .8, t * .05), vec2(1., 2.), .035, 1.3, 2., vec3(1., .1, .1)) * 1.;
    col += lines(p + vec2(.2, .4) - vec2(-t * .8, -t * .05), vec2(1., 2.), .035, 1.3, 2., vec3(.1, 1., 1.)) * 1.;
    col += lines(p + vec2(.6, .8) - vec2(-t * .6, t * .05), vec2(2., 4.), .025, 1., 1.8, vec3(1., .1, .1)) * .8;
    col += lines(p + vec2(1., 1.2) - vec2(-t * .6, -t * .05), vec2(2., 4.), .025, 1., 1.8, vec3(.1, 1., 1.)) * .8;
    col += lines(p + vec2(1.4, 1.6) - vec2(-t * .4, t * .05), vec2(3., 5.), .015, .8, 1.6, vec3(1., .1, .1)) * .7;
    col += lines(p + vec2(1.8, 2.) - vec2(-t * .4, -t * .05), vec2(3., 5.), .015, .8, 1.6, vec3(.1, 1., 1.)) * .7;
    col += lines(p + vec2(2.2, 2.4) - vec2(-t * .2, t * .05), vec2(4., 6.), .008, .6, 1.4, vec3(1., .1, .1)) * .6;
    col += lines(p + vec2(2.6, 2.8) - vec2(-t * .2, -t * .05), vec2(4., 6.), .008, .6, 1.4, vec3(.1, 1., 1.)) * .6;

    fragColor = vec4(col,1.0);
}
